// Авторский модуль C++20. Примеры запускаются исключительно apps/runner.
export const lessons = [];
function add(
  id,
  title,
  model,
  mechanics,
  trace,
  pitfall,
  experiment,
  demo,
  output,
  task,
  solution,
  expected,
  question,
  answer,
  wrong,
  objectives,
  hint1,
) {
  lessons.push({
    id,
    title,
    model,
    mechanics,
    trace,
    pitfall,
    experiment,
    demo,
    output,
    task,
    solution,
    expected,
    question,
    answer,
    wrong,
    objectives,
    hint1,
  });
}
add(
  'object-lifetime',
  'Время жизни объекта — Object lifetime',
  'Объект в C++ — это не участок памяти, а участок памяти с типом, состоянием и интервалом существования. Время жизни начинается, когда инициализация завершена, и заканчивается, когда начинается вызов деструктора. Память при этом может существовать дольше объекта: байты стекового кадра никуда не исчезают в момент выхода из блока, но объекта в них уже нет. Обращение к памяти, где объект уже не жив, — undefined behavior, даже если старые байты ещё хранят прежнее значение и чтение «выдаёт правильный ответ».',
  'Различайте три сущности: переменную-указатель, объект по её адресу и владельца, отвечающего за освобождение. Указатель может пережить объект: delete не ищет и не обнуляет все копии адреса, поэтому ненулевой указатель не доказывает существование объекта. Напротив, копия значения int полностью независима от источника и может безопасно пережить его — именно поэтому результат вычислений возвращают по значению. Отдельный тонкий случай: после освобождения аллокатор может выдать тот же адрес новому объекту. Совпадение адреса не даёт старому заёмщику права доступа: разрешение связано с объектом, а не с числом.',
  '1. Внешний total создан, значение 0\n2. Вход в блок: создан reading, значение 42\n3. total получает КОПИЮ значения 42; связь с reading не сохраняется\n4. Выход из блока: reading мёртв, память кадра ещё существует\n5. total жив и хранит 42; чтение total законно',
  'Случайно правильное значение из освобождённой памяти не делает чтение законным. Undefined behavior не обязано приводить к падению: программа может работать на отладочной сборке и ломаться на релизной. Корректность исходника нельзя оценивать по ожидаемому stdout.',
  'Замените копирование значения сохранением адреса &reading и прочитайте его после блока. Отметьте точную границу — закрывающую скобку, после которой разыменование становится недопустимым. Не запускайте дефектный вариант вне sandbox.',
  'int main() { int total = 0; { int reading = 42; total = reading; } std::cout << total << "\\n"; }',
  '42\n',
  'В solve(a,b) создайте во вложенном блоке локальное измерение a+b и скопируйте его значение во внешнюю переменную. Верните значение после завершения блока. Не возвращайте адрес или ссылку на локальную переменную.',
  'int solve(int a,int b) { int result = 0; { int sample = a + b; result = sample; } return result; }',
  'sum',
  'Что доказывает ненулевой указатель после удаления объекта?',
  'Только наличие сохранённого ненулевого значения адреса',
  'Что объект по этому адресу всё ещё существует',
  [
    'Различать память, объект и значение и называть границы времени жизни объекта.',
    'Проследить на MemoryDiagram создание и завершение объекта во вложенном блоке.',
    'Вернуть результат вычисления по значению, не создавая висячих адресов.',
  ],
  'Выпишите для каждого объекта момент создания и момент завершения жизни. Копия значения не зависит от источника; адрес источника умирает вместе с объектом.',
);
add(
  'scope-lifetime',
  'Область видимости и время жизни — Scope и lifetime',
  'Scope отвечает на вопрос, где в исходном тексте разрешено употреблять имя. Lifetime отвечает на вопрос, существует ли объект в данный момент исполнения. Для простой локальной переменной эти интервалы совпадают, и совпадение порождает путаницу. Затенение имени во вложенном блоке не уничтожает внешний объект. Локальная static-переменная хранит объект между вызовами функции, хотя имя доступно только внутри неё. Динамический объект переживает блок создания, если владение вынесено наружу, а ссылка на локальный объект не переживает возврат из функции.',
  'Ссылка — дополнительное имя существующего объекта, а не владелец. Локальная const-ссылка, напрямую привязанная к временному объекту, продлевает его жизнь до конца своей области: const std::string& s = std::string{"ok"} законно. Но продление не передаётся через возвраты: если функция приняла const T& и вернула её же, временный объект вызывающего умрёт в конце полного выражения. std::string_view и std::span не продлевают жизнь данным никогда. В C++20 временные объекты разрушаются в конце полного выражения; для результата вычисления надёжнее всего возвращать владеющее значение — NRVO и устранение копий делают это бесплатным.',
  '1. Внешний value = 4 создан\n2. Вход в блок: внутренний value = 9 создан; внешнее ИМЯ затенено, внешний ОБЪЕКТ жив\n3. Вывод 9 через внутреннее имя\n4. Выход из блока: внутренний value уничтожен\n5. Имя value снова обозначает внешний объект; вывод 4',
  'Не возвращайте const int& на локальную переменную: const запрещает изменение через ссылку, но не хранит объект. Тот же дефект встречается у string_view на временную строку, у span на временный vector и у ссылок на элементы возвращённого по значению контейнера.',
  'Постройте две временные шкалы: для const auto& s = std::string{"abc"} и для std::string_view v = std::string{"abc"}. В первом случае строка живёт вместе со ссылкой; во втором умирает в конце выражения инициализации, а view остаётся указывать на освобождённый буфер.',
  'int main() { int value = 4; { int value = 9; std::cout << value << " "; } std::cout << value << "\\n"; }',
  '9 4\n',
  'Исправьте factory: результат a+b должен безопасно пережить возврат из функции. solve вызывает factory и возвращает полученное значение. Сохраните factory отдельной функцией.',
  'int factory(int a, int b) { int value = a + b; return value; }\nint solve(int a, int b) { return factory(a, b); }',
  'sum',
  'Уничтожает ли затенение имени внешний объект?',
  'Нет: внешний объект жив, скрыто только его имя',
  'Да: внутреннее объявление заменяет внешний объект',
  [
    'Различать scope имени и lifetime объекта на примерах затенения и static.',
    'Проследить на MemoryDiagram независимость двух объектов с одним именем.',
    'Диагностировать висячую ссылку при возврате и исправить функцию на возврат по значению.',
  ],
  'Для каждой ссылки назовите объект, на который она указывает, и событие, завершающее жизнь этого объекта. Затенение влияет на имена, а не на объекты.',
);
add(
  'construction-destruction',
  'Конструктор, деструктор и время жизни',
  'Сложный объект создаётся изнутри наружу: сначала базовые подобъекты, затем поля строго в порядке объявления, и только потом выполняется тело конструктора. Порядок записей в списке инициализации ничего не переставляет. Разрушение зеркально: тело деструктора, затем поля в обратном порядке объявления, затем базы. Объект считается полностью существующим лишь после завершения конструктора и перестаёт существовать в начале деструктора — это и есть формальные границы времени жизни.',
  'Если конструктор бросает исключение, полного объекта нет и его деструктор не вызывается; уже созданные базы и поля разрушаются автоматически. Поэтому поле-владелец (unique_ptr, vector) безопаснее сырого указателя, которому присвоили new в теле конструктора: при последующем исключении сырой адрес не освободит никто. Деструктор не должен бросать: при раскрутке стека исключение из деструктора ведёт к terminate. Виртуальные вызовы в конструкторе и деструкторе не диспетчеризуются в производный класс — самого производного объекта в эти моменты ещё (или уже) нет.',
  'Создание: first → second → тело Pair\nРазрушение: тело ~Pair → second → first\nПоле, объявленное первым, умирает последним\nЕсли second бросает: first разрушается; ~Pair НЕ вызывается',
  'Зависимость от поля, объявленного ниже, не лечится перестановкой инициализаторов: порядок задаёт объявление. Если Session в деструкторе обращается к Buffer, Buffer обязан быть объявлен раньше — иначе он уже мёртв.',
  'Добавьте исключение после создания первого Guard и предскажите журнал. Затем перенесите бросок внутрь конструктора второго Guard до его завершения: в журнале не появится парный минус второго объекта — его деструктор не вызывается.',
  'struct Guard { int id; explicit Guard(int n): id(n) { std::cout << "+" << n << " "; } ~Guard() { std::cout << "-" << id << " "; } };\nint main() { { Guard a{1}; { Guard b{2}; Guard c{3}; } } std::cout << "\\n"; }',
  '+1 +2 +3 -3 -2 -1 \n',
  'Создайте Guard(int& count), увеличивающий count в конструкторе и уменьшающий в деструкторе; копирование запретите. solve(a,b) начинает с count=a, во вложенном блоке создаёт два Guard, сохраняет пиковое значение count, выходит из блока и возвращает peak + count + b.',
  'struct Guard { int& n; explicit Guard(int& x): n(x) { ++n; } ~Guard() { --n; } Guard(const Guard&) = delete; Guard& operator=(const Guard&) = delete; };\nint solve(int a, int b) { int n = a, peak; { Guard x{n}; Guard y{n}; peak = n; } return peak + n + b; }',
  'guards',
  'Вызывается ли деструктор класса, если его конструктор бросил исключение?',
  'Нет; автоматически очищаются только успешно созданные базы и поля',
  'Да: деструктор вызывается всегда, как только выделена память',
  [
    'Объяснить порядок конструирования и разрушения сложного объекта через порядок объявления полей.',
    'Проследить на MemoryDiagram журнал создания и разрушения вложенных Guard.',
    'Реализовать Guard со счётчиком и запретом копирования, предсказав пиковое состояние.',
  ],
  'Журнал «+1 +2 -2 -1» — наблюдаемый порядок жизни. Для каждого объекта назовите момент, когда он полностью создан, и момент, когда начался его деструктор.',
);
add(
  'raii',
  'RAII — ресурс связан с владельцем',
  'RAII связывает право владения ресурсом со временем жизни объекта стека. Ресурсом может быть память, файл, захваченный mutex или временно изменённое состояние. Конструктор приобретает ресурс либо сообщает о неуспехе; методы работают только с допустимым состоянием; деструктор освобождает ресурс на всех путях выхода — при обычном return, при раннем выходе и при раскрутке исключения. Клиенту больше не нужно дублировать cleanup перед каждым выходом: за него это делает область видимости.',
  'У владельца нужно отдельно решить вопрос копирования и перемещения. Для guard, восстанавливающего настройку, копирование почти всегда ошибочно: два экземпляра восстановят одно значение дважды. Guard, заимствующий int&, обязан жить меньше самого int — сначала объявляется защищаемое состояние, затем guard. Деструктор не должен бросать. RAII обеспечивает очистку ресурсов, но не откатывает предметные изменения: добавленная запись в журнал и незакрытый файл — разные обязательства; для транзакции нужен явный договор commit/rollback.',
  '1. level = 5\n2. Guard сохраняет old = 5; level = 50\n3. throw внутри блока → раскрутка → ~Guard\n4. level снова 5; Guard уничтожен\n5. Любой другой выход из блока дал бы тот же результат',
  'Не разбрасывайте delete и unlock по веткам — но и не считайте RAII гарантией при kill процесса или abort: эти примеры относятся к нормальному выходу и раскрутке стека.',
  'Добавьте ранний return и throw внутрь защищённого блока: в обоих случаях настройка восстанавливается. Сравните с ручным присваиванием в конце блока — до него исполнение может не дойти.',
  'struct Restore { int& x; int old; Restore(int& v, int next): x(v), old(v) { x = next; } ~Restore() { x = old; } Restore(const Restore&) = delete; Restore& operator=(const Restore&) = delete; };\nint main() { int level = 5; try { Restore g{level, 50}; std::cout << level << " "; throw 1; } catch (int) {} std::cout << level << "\\n"; }',
  '50 5\n',
  'Реализуйте Restore как в модели: конструктор сохраняет прежнее значение ссылки и записывает новое, деструктор восстанавливает, копирование запрещено. solve(a,b) временно заменяет a на b, сохраняет изменённое значение, бросает int и ловит его снаружи блока Restore; верните сумму сохранённого и восстановленного значений.',
  'struct Restore { int& x; int old; Restore(int& v, int next): x(v), old(v) { x = next; } ~Restore() { x = old; } Restore(const Restore&) = delete; Restore& operator=(const Restore&) = delete; };\nint solve(int a, int b) { int inside = 0; try { Restore g{a, b}; inside = a; throw 1; } catch (int) {} return inside + a; }',
  'sum',
  'Что обеспечивает освобождение ресурса при исключении?',
  'Деструктор успешно созданного автоматического владельца при раскрутке стека',
  'Код cleanup, записанный после throw в том же блоке',
  [
    'Объяснить, почему привязка ресурса к времени жизни объекта закрывает все пути выхода.',
    'Проследить на MemoryDiagram восстановление состояния при раскрутке исключения.',
    'Реализовать небросаемый guard с запретом копирования и проверить его на исключении.',
  ],
  'Перечислите все пути выхода из защищённого блока: обычный конец, return, throw. Деструктор владельца выполняется на каждом из них.',
);
add(
  'ownership',
  'Владение и заимствование — Ownership',
  'Владелец отвечает за прекращение использования и освобождение ресурса; заёмщик получает временный доступ и не освобождает ничего. Один адрес может находиться у многих наблюдателей, но количество копий адреса не определяет количество владельцев: владелец ровно тот, кто обязан освободить ресурс. Современный C++ выражает роли типами параметров: const T& — чтение заимствованного объекта, T& — изменяемое заимствование, unique_ptr<T> по значению — передача исключительного владения, shared_ptr<T> по значению — вступление в совместное владение.',
  'Сырой T* не сообщает, кто вызывает delete: для чужого API это нужно выяснять по контракту — получен указатель из new, malloc, библиотечной create-функции или это адрес поля. Функция inspect не должна удалять переданный объект только потому, что получила указатель; функция, сохраняющая адрес «на потом», обязана согласовать срок заимствования с временем жизни владельца. Не принимайте shared_ptr только для синхронного чтения: это навязывает клиенту способ хранения и атомарную работу со счётчиком там, где достаточно const T&.',
  'Владелец owner ──владеет──> int(7)\nЗаёмщик inspect(const int&) - - читает -> тот же int\nПосле вызова владельцем остаётся owner\nКонец owner: объект удалён; сохранённые сырые адреса больше нельзя разыменовывать',
  'Договор «удалит кто-нибудь из вызывающих» допускает и утечку, и повторное удаление. Передача сырого адреса сама по себе владение не передаёт.',
  'Сравните inspect(const int&) и consume(std::unique_ptr<int>): в первом случае объект остаётся у владельца, во втором исходный unique_ptr после вызова пуст. Вызов consume(std::move(owner)) делает передачу видимой в коде клиента.',
  'int describe(const std::string& s) { return static_cast<int>(s.size()); }\nint main() { auto name = std::make_unique<std::string>("sensor"); std::cout << describe(*name) << " " << *name << "\\n"; }',
  '6 sensor\n',
  'Исправьте inspect: он должен заимствовать int через const int&, возвращать значение, не удалять объект и не сохранять адрес. solve создаёт unique_ptr со значением a, вызывает inspect и возвращает inspect(*owner) + b; владельцем до конца остаётся owner.',
  'int inspect(const int& x) { return x; }\nint solve(int a, int b) { auto owner = std::make_unique<int>(a); return inspect(*owner) + b; }',
  'sum',
  'Как типом параметра выразить передачу исключительного владения?',
  'std::unique_ptr<T> по значению — клиент обязан написать std::move',
  'const T& — ссылка ничего не передаёт',
  [
    'Называть владельца и заёмщика для каждого адреса в программе.',
    'Проследить на MemoryDiagram, что заимствование не меняет владельца.',
    'Диагностировать нарушение договора заимствования и исправить интерфейс на const T&.',
  ],
  'Для каждой функции ответьте на четыре вопроса: изменяет ли объект, сохраняет ли доступ, освобождает ли, допускает ли null. Сырой указатель не отвечает ни на один из них типом.',
);
add(
  'copy-constructor',
  'Конструктор копирования — Copy constructor',
  'Конструктор копирования создаёт новый объект из существующего; стандартная сигнатура — T(const T& other). Запись T b = a является инициализацией: объекта b ещё не было, оператор присваивания не участвует. Для класса без пользовательских правил компилятор копирует базы и поля их собственными операциями: int копирует число, vector — элементы, сырой указатель — только адрес. Поэтому смысл копии определяет не компилятор, а контракт типа.',
  'У значения (измерение, строка) изменение копии не должно менять оригинал — нужна глубокая копия. У дескриптора общего объекта копия может намеренно разделять состояние. У исключительного владельца копирование запрещают через = delete. В примере Measurement владеет одним int: её копирующий конструктор выделяет новый int и копирует значение. Если выделение бросит, новый объект не создан, а источник не изменён — это сильная гарантия. Присваивание здесь запрещено: хороший конструктор копирования не исправляет автоматически опасный operator=, это отдельная операция.',
  'a.value ──> блок A: 10\nMeasurement b = a: выделить блок B; скопировать 10 в B\nb.value ──> блок B: 10\n*b.value = 25: блок B хранит 25; блок A остаётся 10',
  'Сигнатура T(T other) невозможна как конструктор копирования: передача параметра сама потребовала бы копирования. Передачу больших объектов только для чтения выполняйте через const T&.',
  'После создания копии b измените её значение, затем уничтожьте b во вложенном блоке и прочитайте a. Проверка наблюдает одновременно независимость значений и освобождение разных блоков.',
  'struct Measurement { std::unique_ptr<int> value; explicit Measurement(int v): value(std::make_unique<int>(v)) {} Measurement(const Measurement& other): value(std::make_unique<int>(*other.value)) {} Measurement& operator=(const Measurement&) = delete; };\nint main() { Measurement a{10}; Measurement b = a; *b.value = 25; std::cout << *a.value << " " << *b.value << "\\n"; }',
  '10 25\n',
  'Создайте Measurement с владеющим unique_ptr<int>, конструктором от int и глубоко копирующим конструктором; присваивание запретите. solve создаёт first(a), копию second(first), меняет значение second на b и возвращает сумму значений двух объектов.',
  'struct Measurement { std::unique_ptr<int> value; explicit Measurement(int v): value(std::make_unique<int>(v)) {} Measurement(const Measurement& other): value(std::make_unique<int>(*other.value)) {} Measurement& operator=(const Measurement&) = delete; };\nint solve(int a, int b) { Measurement first{a}; Measurement second{first}; *second.value = b; return *first.value + *second.value; }',
  'sum',
  'Какая операция выполняется в записи Measurement b = a?',
  'Конструктор копирования: объект b создаётся',
  'Копирующее присваивание: объект b уже существует',
  [
    'Отличать инициализацию копированием от присваивания по наличию объекта назначения.',
    'Проследить на MemoryDiagram создание независимого блока при глубокой копии.',
    'Реализовать глубоко копирующий конструктор и обосновать запрет присваивания.',
  ],
  'Сравните адреса ресурсов оригинала и копии. Одинаковый адрес у двух владельцев — признак поверхностной копии.',
);
add(
  'copy-assignment',
  'Копирующее присваивание — Copy assignment',
  'Присваивание заменяет состояние уже существующего объекта. В записи target = source у target может быть собственный ресурс, который нужно корректно освободить, — это первое отличие от конструктора копирования. Обычная сигнатура T& operator=(const T&) возвращает *this для поддержки цепочек a = b = c. Помимо обычного случая нужно учесть самоприсваивание через ссылку-алиас и исключение при выделении нового ресурса.',
  'Безопасная последовательность: сначала подготовить полную замену во временного владельца, затем заменить старый ресурс. Если выделение не удалось, назначение не изменено — это сильная гарантия исключений. Copy-and-swap обобщает идею: временная копия строится до любых изменений, обмен состояниями не бросает, прежнее состояние назначения уничтожает временный объект. Цена — возможно лишнее выделение: для больших буферов иногда нужна версия с переиспользованием ёмкости, но её доказательство заметно сложнее.',
  'До: target → A(3); source → B(7)\nПодготовка: temporary → C(7); A и B ещё живы\nCommit: target → C; temporary → A\nОчистка: A освобождён; source по-прежнему → B',
  'Порядок «delete p; p = new int(*other.p)» опасен дважды: при самоприсваивании other.p указывает на уже удалённый int, а при исключении target остаётся повреждённым.',
  'Проверьте три сценария: присваивание разных объектов, самоприсваивание через alias и независимость после изменения источника. На бумаге вставьте bad_alloc между подготовкой и commit: старое состояние должно остаться целым.',
  'struct Cell { std::unique_ptr<int> p; explicit Cell(int x): p(std::make_unique<int>(x)) {} Cell(const Cell&) = delete; Cell& operator=(const Cell& x) { auto next = std::make_unique<int>(*x.p); p = std::move(next); return *this; } };\nint main() { Cell a{3}, b{7}; a = b; *b.p = 9; std::cout << *a.p << " " << *b.p << "\\n"; }',
  '7 9\n',
  'Реализуйте Box::operator= с подготовкой нового unique_ptr до замены старого. solve создаёт x(a) и y(b), выполняет x = y, затем самоприсваивание через ссылку alias на x, меняет значение y на a и возвращает *x.p + *y.p.',
  'struct Box { std::unique_ptr<int> p; explicit Box(int x): p(std::make_unique<int>(x)) {} Box(const Box&) = delete; Box& operator=(const Box& x) { auto next = std::make_unique<int>(*x.p); p = std::move(next); return *this; } };\nint solve(int a, int b) { Box x{a}, y{b}; x = y; Box& alias = x; x = alias; *y.p = a; return *x.p + *y.p; }',
  'sum',
  'Когда освобождать прежний ресурс ради сильной гарантии исключений?',
  'После успешного создания нового ресурса',
  'До попытки копирования нового ресурса',
  [
    'Перечислить три дополнительные проблемы присваивания по сравнению с конструктором копии.',
    'Проследить на MemoryDiagram подготовку замены до фиксации нового состояния.',
    'Реализовать operator=, переживающий самоприсваивание и исключение при выделении.',
  ],
  'Проверьте присваивание на трёх входах: другой объект, тот же объект через алиас, бросок при выделении. Порядок «сначала подготовить, затем заменить» проходит все три.',
);
add(
  'shallow-copy',
  'Поверхностное копирование — Shallow copy',
  'Поверхностная копия переносит непосредственные поля: для указателя копируется адрес, а не объект по адресу. Для невладеющего представления это нормально — два View намеренно наблюдают один int. Для класса, чей деструктор удаляет этот int, это катастрофа: после неявного копирования два экземпляра считают один ресурс своим. Первый деструктор освобождает блок, второй пытается освободить его ещё раз — double delete.',
  'Сначала определите смысл типа, затем способ копирования. Представление — уберите удаление и гарантируйте внешнего владельца. Самостоятельное значение — создавайте глубокую копию. Исключительный владелец — запретите копирование и разрешите перемещение. Обнуление p только в одном экземпляре не лечит вторую копию; удаление одного delete вручную в main оставляет класс ошибочным при другом порядке разрушения. Диагностическая таблица: один new и два права на освобождение — красный флаг; два new и два владельца — корректная глубокая копия; один new, один владелец и несколько заёмщиков — тоже корректно.',
  'До копии: a.p → блок A(7)\nПосле неявной копии: a.p → A(7) ← b.p; два права на один блок\n~b освобождает A\n~a повторяет delete A — double delete',
  'Нельзя лечить double delete удалением всех деструкторов: вместе с падением исчезает и освобождение ресурса. Исправление должно объяснять единственного владельца либо независимость копий.',
  'Для View безопасно изменить объект через владельца и увидеть изменение через обе копии представления. Для владеющего Box ожидается противоположный тест: изменение копии не затрагивает оригинал.',
  'struct View { int* p; };\nint main() { int x = 3; View a{&x}; View b = a; x = 11; std::cout << *a.p << " " << *b.p << "\\n"; }',
  '11 11\n',
  'Исправьте Box с сырым int* и деструктором: копия должна владеть отдельным int. Добавьте глубокий копирующий конструктор и запретите копирующее присваивание. solve создаёт first(a), во вложенном блоке копию second, меняет её значение на b и сохраняет его; после уничтожения second возвращает сохранённое.',
  'struct Box { int* p; explicit Box(int x): p(new int(x)) {} Box(const Box& x): p(new int(*x.p)) {} Box& operator=(const Box&) = delete; ~Box() { delete p; } };\nint solve(int a, int b) { int saved; { Box first{a}; { Box second = first; *second.p = b; saved = *second.p; } } return saved + a - b + b; }',
  'sum',
  'Когда поверхностная копия указателя допустима?',
  'У невладеющего заёмщика с гарантированным внешним владельцем',
  'Всегда, если адрес ненулевой',
  [
    'Связать неявное копирование адреса с появлением второго права на освобождение.',
    'Проследить на MemoryDiagram порядок разрушения двух владельцев одного блока.',
    'Диагностировать double delete по фрагментам и исправить Box глубокой копией.',
  ],
  'Посчитайте количество new и количество деструкторов, вызывающих delete. Если их не поровну на каждый блок — найдите строку, где появляется лишнее право.',
);
add(
  'deep-copy',
  'Глубокое копирование — Deep copy',
  'Глубокая копия создаёт независимые ресурсы там, где этого требует семантика значения: для буфера это новый массив и поэлементное копирование. «Глубокая» не означает «рекурсивно скопировать каждый указатель»: часть указателей может быть невладеющей ссылкой на общий сервис, кеш или родителя. Сначала решите, какие поля выражают владение, — только они требуют дублирования.',
  'Копирование буфера из n элементов стоит O(n) времени и O(n) памяти — при необходимой независимости это неизбежно. При неуспехе на середине частично заполненный буфер должен очищаться: vector гарантирует это сам. Если элементы vector — shared_ptr, копируется участие в владении, а объекты за указателями остаются общими: vector не гарантирует независимость всего графа. Для графов с общими подграфами и циклами нужен словарь соответствия старых узлов новым; для полиморфных объектов — виртуальный clone.',
  'original → буфер A: 1 2 3\ncopy → буфер B: 1 2 3; адреса A и B различаются\ncopy[0] = 99 → B: 99 2 3\nA остаётся 1 2 3 — значения независимы',
  'Побайтовый memcpy класса с vector или string разрушает инварианты владельца: копируются внутренние адреса представления. Копируйте объекты их операциями, а не сырыми байтами.',
  'Замените vector<int> на vector<shared_ptr<int>> и предскажите, изменится ли объект через копию. Объясните, какой уровень структуры стал независимым, а какой остался общим.',
  'int main() { std::vector<int> original{1, 2, 3}; auto copy = original; copy[0] = 99; std::cout << original[0] << " " << copy[0] << " " << original.size() << "\\n"; }',
  '1 99 3\n',
  'Создайте Buffer с vector<int>. solve заполняет original значениями {a, b}, копирует Buffer, заменяет первый элемент копии на b и возвращает original[0] + copy[0]. Не используйте общий динамический массив для двух Buffer.',
  'struct Buffer { std::vector<int> values; };\nint solve(int a, int b) { Buffer original{{a, b}}; Buffer copy = original; copy.values[0] = b; return original.values[0] + copy.values[0]; }',
  'sum',
  'Какова обычная стоимость глубокой копии буфера из n элементов?',
  'O(n) времени и O(n) новой памяти',
  'O(1) времени независимо от n',
  [
    'Определять, какие поля требуют дублирования, по семантике владения типа.',
    'Проследить на MemoryDiagram независимость двух буферов после копирования.',
    'Реализовать Buffer с независимой копией и объяснить стоимость глубокого копирования.',
  ],
  'Проверьте копию на двух уровнях: изменился ли оригинал при записи в копию и совпадают ли адреса буферов.',
);
add(
  'rule-of-three',
  'Правило трёх — Rule of Three',
  'Если тип вручную управляет ресурсом и ему нужен собственный деструктор, вместе с ним необходимо рассмотреть конструктор копирования и копирующее присваивание. Это правило проектирования, а не требование написать три тела любой ценой: для исключительного ресурса обе копии законно удалить, для значения они должны создавать независимое содержимое. Ошибка возникает, когда написан только ~Buffer, а неявные копии продолжают дублировать адрес.',
  'Инвариант учебного Cell прост: p всегда указывает на один собственный int. Деструктор удаляет его; копирующий конструктор выделяет другой int; присваивание сначала выделяет новый блок, затем удаляет старый. Такой порядок переживает самоприсваивание и сохраняет сильную гарантию при bad_alloc. Ручной new показан для понимания механики: в прикладном коде такой Cell лучше выразить готовым владеющим членом. Не добавляйте специальные операции классу, у которого нет соответствующей ответственности.',
  'Конструирование: один Cell → один блок\nКопия: два Cell → два разных блока\nПрисваивание: подготовить новый блок → заменить → удалить старый\nРазрушение: каждый Cell удаляет только свой блок',
  'Одна корректная операция не компенсирует другую опасную. Проверяйте все пути: copy construction, copy assignment после неё и самоприсваивание через алиас.',
  'Постройте цепочку y = x; z = y; затем измените x. Значения y и z должны остаться прежними. Отдельно оцените цену хранения одного int динамически: это учебный способ увидеть владение, а не рекомендация.',
  'struct Cell { int* p; explicit Cell(int x): p(new int(x)) {} ~Cell() { delete p; } Cell(const Cell& x): p(new int(*x.p)) {} Cell& operator=(const Cell& x) { int* next = new int(*x.p); delete p; p = next; return *this; } };\nint main() { Cell a{4}; Cell b = a; b = a; *a.p = 6; std::cout << *b.p << "\\n"; }',
  '4\n',
  'Реализуйте Cell по правилу трёх: деструктор, глубокий копирующий конструктор, присваивание с подготовкой замены до удаления старого блока. solve создаёт x(a), копию y, объект z(b), выполняет z = y и самоприсваивание z через алиас, меняет y на b и возвращает *z.p + *y.p.',
  'struct Cell { int* p; explicit Cell(int x): p(new int(x)) {} ~Cell() { delete p; } Cell(const Cell& x): p(new int(*x.p)) {} Cell& operator=(const Cell& x) { int* next = new int(*x.p); delete p; p = next; return *this; } };\nint solve(int a, int b) { Cell x{a}, y = x, z{b}; z = y; Cell& alias = z; z = alias; *y.p = b; return *z.p + *y.p; }',
  'sum',
  'Что правило трёх разрешает сделать с копированием исключительного владельца?',
  'Явно запретить обе копирующие операции через = delete',
  'Оставить неявную поверхностную копию владеющего указателя',
  [
    'Сформулировать инвариант владельца до написания трёх специальных операций.',
    'Проследить на MemoryDiagram transitions блоков при копии, присваивании и разрушении.',
    'Реализовать Cell по правилу трёх, переживающий самоприсваивание и bad_alloc.',
  ],
  'Проверьте каждую операцию как переход между допустимыми состояниями: копия не меняет источник, присваивание освобождает старое, деструктор удаляет ровно свой блок.',
);
add(
  'move-semantics',
  'Семантика перемещения — Move semantics',
  'Перемещение позволяет новому владельцу принять ресурс, которым источник больше не пользуется в прежнем состоянии. Это семантика операции, а не перенос байтов на другой адрес: объект-источник продолжает существовать и будет разрушен своим деструктором. У unique_ptr после передачи владения источник пуст, а выделенный int остаётся на прежнем адресе — заёмщики самого int остаются корректными до удаления новым владельцем. Для других типов допустимое состояние после перемещения определяется их контрактом.',
  'Копирование и перемещение отвечают на разные вопросы: копия сохраняет независимый источник, перемещение переиспользует его ресурс. Но move не обязательно дешевле и не обязательно перемещает: для int это фактически копирование, а при отсутствии move-конструктора std::move тихо выберет копию — компиляция успешна, выигрыша нет. У стандартных типов moved-from состояние допустимое, но не определённое заранее, если контракт не обещает большего: разрушить объект можно, вызвать front у потенциально пустого vector — нет.',
  'До: source → A(15); destination не существует\nПередача: destination принимает адрес A\nПосле: source пуст, но жив; destination → A(15)\nРазрушение source ничего не удаляет; A удалит destination',
  'Нельзя разыменовывать moved-from unique_ptr через *source. Сам source можно проверять, сбрасывать и заполнять заново. Не переносите гарантию пустоты unique_ptr на произвольный класс.',
  'Сохраните сырой адрес до передачи и сравните с destination.get() после: адреса совпадут — сам int не переезжал. Затем назначьте source новый ресурс и убедитесь, что он снова полноценный владелец.',
  'int main() { auto src = std::make_unique<int>(15); auto dst = std::move(src); std::cout << (src ? 1 : 0) << " " << *dst << " " << (dst ? 1 : 0) << "\\n"; }',
  '0 15 1\n',
  'В solve создайте source со значением a, переместите его в destination, проверьте пустоту source, затем назначьте source новый int(b). Верните сумму значений; если источник после передачи не пуст, верните -9999.',
  'int solve(int a, int b) { auto source = std::make_unique<int>(a); auto destination = std::move(source); if (source) return -9999; source = std::make_unique<int>(b); return *source + *destination; }',
  'sum',
  'Что происходит с объектом-источником после перемещения?',
  'Он продолжает существовать в состоянии, определённом контрактом типа',
  'Его деструктор немедленно вызывается',
  [
    'Объяснить перемещение как передачу права на ресурс при живом объекте-источнике.',
    'Проследить на MemoryDiagram, что адрес ресурса не меняется, меняется владелец.',
    'Проверить пустоту источника после передачи и восстановить его новым ресурсом.',
  ],
  'Разделите два вопроса: что стало с ресурсом и что стало с объектом-источником. Ресурс сменил владельца; объект жив до конца своей области.',
);
add(
  'rvalue-references',
  'Rvalue-ссылки — Rvalue references',
  'Категория значения принадлежит выражению, а не переменной навсегда. lvalue обозначает объект с устойчивой идентичностью — у него можно взять адрес. prvalue вычисляет значение и инициализирует объект. xvalue обозначает объект, ресурсы которого разрешено переиспользовать; rvalue объединяет prvalue и xvalue. Ссылка T&& связывается с rvalue и даёт перегрузкам способ отличать заимствование для чтения от разрешения потребить состояние.',
  'Именованный параметр T&& внутри функции — lvalue-выражение: у него есть имя, и его можно использовать несколько раз. Чтобы передать разрешение на перемещение дальше, нужен явный std::move; само связывание ссылки ничего не переносит. const T& принимает и lvalue, и rvalue для чтения. Не смешивайте rvalue-ссылку конкретного типа с forwarding reference T&& в шаблоне с выводимым T: там действуют вывод типа и схлопывание ссылок — это отдельная тема perfect forwarding.',
  'int value = 9           → выражение value: lvalue\nstd::move(value)         → xvalue; объект тот же\nint&& ref = ...          → ref обозначает value\nВыражение ref            → lvalue, несмотря на тип int&&',
  'Тип int&& не делает каждое использование имени перемещением: иначе повторное чтение параметра молча опустошало бы объект. Категорию задаёт форма выражения, а не объявленный тип.',
  'Замените route(std::move(ref)) на route(ref) и предскажите выбранную перегрузку. Затем добавьте const int и объясните, почему int&& не связывается с const xvalue.',
  'int route(const int&) { return 1; } int route(int&&) { return 2; }\nint main() { int value = 9; int&& ref = std::move(value); std::cout << route(ref) << " " << route(std::move(ref)) << " " << route(5) << "\\n"; }',
  '1 2 2\n',
  'Реализуйте route(const int&) с результатом 1 и route(int&&) с результатом 2. solve(a,b) связывает int&& ref со std::move(a) и возвращает 10 * route(ref) + route(std::move(b)). Не изменяйте a и b.',
  'int route(const int&) { return 1; } int route(int&&) { return 2; }\nint solve(int a, int b) { int&& ref = std::move(a); return 10 * route(ref) + route(std::move(b)); }',
  '12',
  'Какова категория выражения ref, объявленного как int&& ref?',
  'lvalue: у выражения есть имя',
  'Всегда rvalue: это следует из типа int&&',
  [
    'Классифицировать выражения по категориям lvalue, prvalue и xvalue.',
    'Проследить на MemoryDiagram, почему именованная rvalue-ссылка сама является lvalue.',
    'Реализовать перегрузки route и предсказать выбор компилятора для каждого вызова.',
  ],
  'Для каждого вызова выпишите категорию аргумента: имя переменной — lvalue, std::move(...) — xvalue, литерал — prvalue. Выбор перегрузки следует из категории.',
);
add(
  'std-move',
  'std::move — разрешение на перемещение',
  'std::move — это приведение категории выражения к xvalue с сохранением cv-квалификаторов. Он не выделяет память, не вызывает деструктор и сам ничего не переносит: работу выполняет выбранная перегрузка конструктора или оператора присваивания. Инструкция std::move(x); как отдельный оператор не опустошит x. Имя функции правильнее читать как «этот объект разрешено использовать как источник перемещения».',
  'Если x — const T, результат имеет тип const T&&: типичный move-конструктор T(T&&) не может принять его, потому что изменение источника запрещено, — и доступный T(const T&) молча выполнит копирование. У unique_ptr копирование удалено, поэтому move от const даст честную ошибку компиляции. Для возврата локального значения пишите return result: применяются правила elision; return std::move(result) способно помешать NRVO. Не разбрасывайте move ради скорости — сначала установите, где прежнее состояние больше не нужно.',
  'std::move(x)            → только новая категория выражения\nT y(std::move(x))      → выбор конструктора → возможная передача\nconst T c; move(c)     → const T&&; T(T&&) не подходит\nКопирующая перегрузка принимает const T&& через const T&',
  'Не объявляйте объект const, если собираетесь передать изменяемое владение. Наличие std::move в вызове не является доказательством, что выбрана move-перегрузка.',
  'Probe в примере печатает выбранную перегрузку. Сначала предскажите обе строки без запуска, затем удалите move-конструктор: оба случая будут копировать через const&.',
  'struct Probe { Probe() = default; Probe(const Probe&) { std::cout << "copy "; } Probe(Probe&&) noexcept { std::cout << "move "; } };\nint main() { Probe a; Probe b(std::move(a)); const Probe c; Probe d(std::move(c)); std::cout << "\\n"; }',
  'move copy \n',
  'Создайте Probe с полем kind: конструктор по умолчанию ставит 0, копирующий — 1, перемещающий noexcept — 2. solve создаёт обычный и const Probe, конструирует новый объект из std::move каждого и возвращает 10 * kind первого + kind второго. Аргументы a и b не используются.',
  'struct Probe { int kind = 0; Probe() = default; Probe(const Probe&): kind(1) {} Probe(Probe&&) noexcept: kind(2) {} };\nint solve(int a, int b) { (void)a; (void)b; Probe x; const Probe y; Probe first(std::move(x)), second(std::move(y)); return 10 * first.kind + second.kind; }',
  '21',
  'Что непосредственно делает std::move?',
  'Преобразует категорию выражения, сохраняя cv-квалификаторы',
  'Переносит ресурс и обнуляет источник',
  [
    'Объяснить std::move как приведение категории, а не как операцию переноса.',
    'Проследить на MemoryDiagram, почему move от const выбирает копирующую перегрузку.',
    'Реализовать Probe, фиксирующий выбор перегрузки значением поля kind.',
  ],
  'Для каждого вызова определите, какая перегрузка будет выбрана: тип аргумента после std::move решает всё. const блокирует перемещение.',
);
add(
  'move-constructor',
  'Перемещающий конструктор — Move constructor',
  'Перемещающий конструктор T(T&& other) создаёт нового владельца из источника, ресурсы которого разрешено забрать. Для сырого указателя недостаточно скопировать адрес: нужно лишить источник права освобождения, иначе оба деструктора удалят один блок. Инвариант владельца: p либо null, либо указывает на единственный принадлежащий объекту int. std::exchange(other.p, nullptr) возвращает старый адрес и одновременно переводит источник в пустое состояние одной операцией; delete nullptr в деструкторе безопасен.',
  'Пустое состояние становится частью публичного договора: метод get не может безусловно разыменовывать p. В учебном Cell get возвращает 0 для пустого объекта; другая допустимая политика — предусловие has_value, но его нужно явно проверять. noexcept важен: vector при росте перемещает элементы только если перемещение noexcept или копия недоступна. Но noexcept обязан быть правдой — исключение из noexcept-функции завершает программу через terminate; передача указателя не бросает, поэтому здесь он обоснован.',
  'До: source.p → A; target не существует\nОшибочно: target.p = source.p → два владельца A → double delete\nПравильно: target.p = exchange(source.p, null)\nПосле: source.p = null; target.p → A; оба объекта живы',
  'Неправильный move-конструктор часто компилируется и выдаёт верные значения до выхода из области: ошибка проявляется во втором delete при разрушении. Проверяйте разрушение обоих объектов, а не только напечатанные значения.',
  'Поместите перемещённый объект во внутренний блок и выйдите из него: источник должен остаться допустимым пустым объектом. Затем переместите уже пустой источник ещё раз и проверьте, что ничего не падает.',
  'struct Cell { int* p; explicit Cell(int n): p(new int(n)) {} ~Cell() { delete p; } Cell(const Cell&) = delete; Cell& operator=(const Cell&) = delete; Cell(Cell&& x) noexcept : p(std::exchange(x.p, nullptr)) {} int get() const { return p ? *p : 0; } };\nint main() { Cell a{20}; Cell b(std::move(a)); std::cout << a.get() << " " << b.get() << "\\n"; }',
  '0 20\n',
  'Исправьте move-конструктор Cell: передавайте указатель с обнулением источника, копирование запрещено. get пустого Cell возвращает 0. solve создаёт source(a), перемещает его во вложенный target, сохраняет target.get() + b; после блока проверяет source.get() == 0 и возвращает сохранённое, иначе -9999.',
  'struct Cell { int* p; explicit Cell(int n): p(new int(n)) {} ~Cell() { delete p; } Cell(const Cell&) = delete; Cell& operator=(const Cell&) = delete; Cell(Cell&& x) noexcept : p(std::exchange(x.p, nullptr)) {} int get() const { return p ? *p : 0; } };\nint solve(int a, int b) { Cell source{a}; int saved; { Cell target(std::move(source)); saved = target.get() + b; } return source.get() == 0 ? saved : -9999; }',
  'sum',
  'Зачем обнулять сырой указатель источника при перемещении?',
  'Чтобы источник потерял право освободить переданный ресурс',
  'Чтобы изменить адрес самого выделенного объекта',
  [
    'Сформулировать инвариант «один блок — один владелец» для перемещающего конструктора.',
    'Проследить на MemoryDiagram обнуление источника через std::exchange.',
    'Диагностировать move-конструктор с двумя владельцами и исправить его обменом указателя.',
  ],
  'После передачи проверьте два состояния: target владеет блоком, source пуст. Доведите оба объекта до разрушения — именно там проявляется ошибка.',
);
add(
  'move-assignment',
  'Перемещающее присваивание — Move assignment',
  'В target = std::move(source) целевой объект уже существует и может владеть другим ресурсом. Перемещающее присваивание обязано освободить прежнее состояние target, принять состояние source и оставить оба объекта допустимыми. Если просто переписать target.p, старый ресурс утечёт; если не обнулить source, появятся два владельца одного адреса. Это конструктор копирования работает на пустом месте — присваивание всегда имеет дело с живым назначением.',
  'Для нашего Cell самоперемещение сохраняет значение: проверка this != &other делает операцию безопасным no-op. Это выбранная гарантия класса, а не универсальное обещание всех типов — публикуйте и тестируйте именно свой контракт. Для разных объектов delete p освобождает прежний ресурс, затем exchange забирает адрес источника. Здесь нет выделения и исключений, поэтому noexcept обоснован. Если владелец хранит ещё размер или deleter, переносить нужно согласованное состояние целиком.',
  'До: target → A(3), source → B(7)\n1. target освобождает A\n2. target принимает B\n3. source становится пуст\nПосле: единственный владелец B — target; A больше не занят',
  'Не пишите p = other.p без очистки прежнего ресурса. Проверка только значений не обнаруживает утечку: нужны сценарий непустого назначения и диагностика памяти.',
  'Проверьте четыре случая: непустой в непустой, непустой в пустой, пустой в непустой и самоперемещение через ссылку-алиас. В последнем случае значение должно сохраниться.',
  'struct Cell { std::unique_ptr<int> p; explicit Cell(int x): p(std::make_unique<int>(x)) {} Cell& operator=(Cell&& x) noexcept { if (this != &x) p = std::move(x.p); return *this; } };\nint main() { Cell a{1}, b{6}; a = std::move(b); std::cout << *a.p << " " << (b.p ? 1 : 0) << "\\n"; }',
  '6 0\n',
  'Реализуйте Cell с сырым int*, деструктором, удалёнными копиями и move-присваиванием noexcept, сохраняющим значение при самоперемещении; get пустого Cell возвращает 0. solve создаёт x(a) и y(b), выполняет x = move(y), затем самоперемещение x через алиас и возвращает x.get() + y.get().',
  'struct Cell { int* p; explicit Cell(int x): p(new int(x)) {} ~Cell() { delete p; } Cell(const Cell&) = delete; Cell& operator=(const Cell&) = delete; Cell& operator=(Cell&& x) noexcept { if (this != &x) { delete p; p = std::exchange(x.p, nullptr); } return *this; } int get() const { return p ? *p : 0; } };\nint solve(int a, int b) { Cell x{a}, y{b}; x = std::move(y); Cell& alias = x; x = std::move(alias); return x.get() + y.get(); }',
  'b',
  'Чем move-присваивание отличается от move-конструктора?',
  'У назначения уже может быть ресурс, который нужно освободить',
  'Присваивание всегда создаёт новый объект',
  [
    'Перечислить три обязательства move-присваивания: очистить, принять, обнулить источник.',
    'Проследить на MemoryDiagram освобождение прежнего блока назначения.',
    'Реализовать самоперемещение как безопасный no-op с проверкой адресов.',
  ],
  'Самоперемещение — совпадение адресов объектов, а не значений: два Cell с одинаковым числом остаются разными владельцами. Проверяйте this != &other.',
);
add(
  'rule-of-five',
  'Правило пяти — Rule of Five',
  'К трём копирующим операциям управления ресурсом C++11 добавил move-конструктор и move-присваивание. Все пять операций должны поддерживать один инвариант. Механика генерации критична: объявление деструктора или любой копирующей операции подавляет неявную генерацию перемещений — добавили ~T() для логирования, и std::move начал тихо копировать. Компиляция проходит, производительность исчезает.',
  'Для нашего Cell null означает пустое состояние после перемещения. Копия непустого Cell создаёт независимый int; копия пустого остаётся пустой — без проверки other.p выражение new int(*other.p) разыменует null. Copy-присваивание использует временную копию и swap; move-конструктор забирает указатель; move-присваивание очищает старое и забирает новое. Все пять не обязаны быть доступны: владелец файла может удалить копии, сохранив перемещения. = default и = delete — такие же решения правила пяти.',
  'Состояния: пустой | владеет одним int\ncopy: пустой→пустой; владелец→новый независимый владелец\nmove: источник→пустой; назначение→прежний ресурс источника\ndestruct: пустой→ничего; владелец→ровно одно освобождение',
  'Не забывайте копирование moved-from объекта, если контракт его разрешает: без проверки null копирующий конструктор разыменует пустой указатель.',
  'В практике последовательно используются все пять операций, включая копию пустого объекта. Составьте таблицу владельцев после каждой строки: ни один блок не должен остаться без владельца и ни один — с двумя.',
  'struct Value { std::vector<int> data; Value(): data{5} {} ~Value() = default; Value(const Value&) = default; Value& operator=(const Value&) = default; Value(Value&&) noexcept = default; Value& operator=(Value&&) noexcept = default; };\nint main() { Value a; Value b = a; Value c = std::move(b); std::cout << c.data[0] << " " << a.data[0] << "\\n"; }',
  '5 5\n',
  'Реализуйте Cell с сырым указателем по правилу пяти: пустой get возвращает 0, копия пустого допустима, присваивание через copy-and-swap, перемещения noexcept. solve: x(a); y = x; z(move(y)); empty = y; x = z; x = move(z); измените *x.p на b; верните x.get() + y.get() + z.get() + empty.get().',
  'struct Cell { int* p; explicit Cell(int x): p(new int(x)) {} ~Cell() { delete p; } Cell(const Cell& x): p(x.p ? new int(*x.p) : nullptr) {} Cell& operator=(const Cell& x) { Cell tmp(x); std::swap(p, tmp.p); return *this; } Cell(Cell&& x) noexcept : p(std::exchange(x.p, nullptr)) {} Cell& operator=(Cell&& x) noexcept { if (this != &x) { delete p; p = std::exchange(x.p, nullptr); } return *this; } int get() const { return p ? *p : 0; } };\nint solve(int a, int b) { Cell x{a}; Cell y = x; Cell z(std::move(y)); Cell empty = y; x = z; x = std::move(z); *x.p = b; return x.get() + y.get() + z.get() + empty.get(); }',
  'b',
  'Обязательно ли правило пяти разрешает копирование?',
  'Нет: копирование может быть явно удалено',
  'Да: любой ресурс обязан копироваться',
  [
    'Объяснить, как объявление деструктора влияет на генерацию перемещающих операций.',
    'Проследить на MemoryDiagram таблицу переходов пяти операций между состояниями.',
    'Реализовать Cell по правилу пяти, включая копию пустого объекта.',
  ],
  'Составьте таблицу: для каждой из пяти операций — входное состояние источника и назначения, выходное состояние обоих. Пустое состояние — полноценный участник таблицы.',
);
add(
  'rule-of-zero',
  'Правило нуля — Rule of Zero',
  'Предметный класс обычно не должен вручную управлять освобождением: поля string, vector и unique_ptr уже реализуют все необходимые операции. Правило нуля предлагает не объявлять собственные деструктор и специальные операции, когда готовые члены выражают нужное владение, — компилятор составит операции класса из операций его членов. Каждый не написанный вручную деструктор — это не написанная потенциальная ошибка.',
  'У Report с vector<int> копирование даёт независимые элементы, а перемещение может передать буфер. У Report с unique_ptr копирование недоступно, а перемещение обычно генерируется — это не недостаток: тип сообщает, что ресурс исключительный. Правило нуля не доказывает инварианты автоматически: если объект хранит сырой указатель внутрь своего vector, неявная копия скопирует старый адрес, а реаллокация при перемещении его обесценит. Храните индекс или вычисляйте представление по запросу.',
  'Report a → vector A: 8 2\nReport b = a → vector B: 8 2; специальные операции Report не написаны\nb.samples[0] = 4 → B: 4 2\nA остаётся 8 2; очистку и независимость обеспечивают члены',
  'Даже пустой объявленный деструктор подавляет генерацию перемещений. Не добавляйте ~T() = default без причины и понимания специальных операций.',
  'Добавьте поле std::string title и проверьте независимость копии. Затем добавьте сырой указатель на элемент vector и объясните, почему правило нуля перестало обеспечивать нужный смысл копии.',
  'struct Report { std::vector<int> samples; };\nint main() { Report a{{8, 2}}; auto b = a; b.samples[0] = 4; std::cout << a.samples[0] << " " << b.samples[0] << "\\n"; }',
  '8 4\n',
  'Реализуйте Report с vector<int> samples без единой специальной операции. solve создаёт original{{a, b}}, копию copy, меняет copy.samples[0] на b и возвращает original.samples[0] + copy.samples[0].',
  'struct Report { std::vector<int> samples; };\nint solve(int a, int b) { Report original{{a, b}}; Report copy = original; copy.samples[0] = b; return original.samples[0] + copy.samples[0]; }',
  'sum',
  'Что означает правило нуля?',
  'Поручить управление ресурсами владеющим членам и не писать специальные операции',
  'Никогда не использовать конструкторы вообще',
  [
    'Объяснить, как компилятор составляет операции класса из операций его членов.',
    'Проследить на MemoryDiagram независимость копий, обеспеченную одним vector.',
    'Реализовать Report без специальных операций и найти границу применимости правила.',
  ],
  'Проверьте класс на связанность полей: vector и индекс копируются осмысленно; vector и сырой указатель в его буфер — уже нет.',
);
add(
  'unique-ptr',
  'std::unique_ptr — исключительный владелец',
  'unique_ptr<T> хранит исключительное владение объектом и вызывает deleter при разрушении или reset. Копирование запрещено — типом; перемещение передаёт владение. get возвращает заимствованный адрес без передачи права удаления; operator* и operator-> требуют живого ненулевого объекта; bool проверяет пустоту. Сырой адрес, сохранённый заранее, после reset может стать висячим — unique_ptr не делает безопасными все выданные им указатели.',
  'release отдаёт адрес и прекращает владение без удаления: если никто не примет ответственность, будет утечка. reset удаляет прежний объект и принимает новый адрес; никогда не вызывайте reset(p.get()) на самом владельце — сначала удалится тот самый объект. Для массивов существует unique_ptr<T[]> с парным delete[]; обычный unique_ptr<T> несовместим с new T[n]. Удаление наследника через unique_ptr<Base> требует виртуального деструктора в Base: стандартный deleter вызывает delete через статический тип указателя.',
  'owner → A(9); observer = owner.get() - - заимствует -> A\nsaved = *owner: копия значения 9 независима\nowner.reset(): A удалён, owner пуст\nobserver хранит прежний адрес; разыменование observer — use-after-free',
  'get не создаёт второго владельца и не продлевает жизнь объекта. Сохранённый ранее сырой адрес переживает reset владельца и становится висячим.',
  'Сравните reset и release по двум вопросам: кто удалил объект и кто обязан удалить его теперь. В практике значение нужно получить до reset и хранить независимо от адреса.',
  'int main() { auto owner = std::make_unique<int>(9); int saved = *owner; owner.reset(); std::cout << saved << " " << (owner ? 1 : 0) << "\\n"; }',
  '9 0\n',
  'Исправьте use-after-free: solve создаёт owner(a), сохраняет значение до reset, вызывает reset и возвращает сохранённое + b. Не разыменовывайте сырой адрес после reset и не удаляйте его вручную.',
  'int solve(int a, int b) { auto owner = std::make_unique<int>(a); int saved = *owner; owner.reset(); return saved + b; }',
  'sum',
  'Передаёт ли get() право удаления объекта?',
  'Нет: он возвращает заимствованный адрес, владение остаётся у unique_ptr',
  'Да: после get владелец становится пустым',
  [
    'Различать get, reset и release по последствию для владения.',
    'Проследить на MemoryDiagram момент, когда сохранённый адрес становится висячим.',
    'Диагностировать use-after-free после reset и исправить порядок операций.',
  ],
  'Для каждой операции unique_ptr ответьте: объект удалён? владение прекращено? адрес выдан наружу? Комбинация ответов и отличает get от reset и release.',
);
add(
  'make-unique',
  'std::make_unique — создание владельца',
  'make_unique<T>(args...) создаёт объект T с переданными аргументами и сразу возвращает unique_ptr<T>. Приобретение ресурса и назначение владельца становятся одной операцией: промежуточного сырого адреса, который мог бы утечь между new и конструированием владельца, просто не существует. Если конструктор T бросит, память new-выражения освобождается.',
  'make_unique<int[]>(n) создаёт владеющий массив из n элементов с инициализацией нулями и гарантирует парный delete[]. Размер в unique_ptr не хранится — его нужно вести отдельно; для последовательности переменной длины чаще подходит vector. make_unique не принимает пользовательский deleter: для FILE и библиотечных ресурсов конструируйте unique_ptr<T, D> явно. Не оправдывайте фабрику примерами про порядок вычисления аргументов до C++17 — в C++20 они неактуальны; настоящая причина — отсутствие окна утечки и единая точка владения.',
  'Запрос make_unique<int[]>(4)\nВладелец buffer → массив: 0 0 0 0\nbuffer[3] = 8 → массив: 0 0 0 8\nДеструктор buffer вызывает delete[] автоматически',
  'Не используйте unique_ptr<int[]> как контейнер с проверкой границ: operator[] не проверяет индекс, а длину нужно знать отдельно.',
  'Замените массив на vector<int>(4) и перечислите дополнительные возможности: size, итераторы, изменение длины. Объясните, когда фиксированное отдельное владение массивом всё же уместнее.',
  'int main() { auto buf = std::make_unique<int[]>(4); buf[3] = 8; std::cout << buf[0] << " " << buf[3] << "\\n"; }',
  '0 8\n',
  'В solve создайте make_unique<int[]>(3), запишите a в элемент 0 и b в элемент 2. Верните сумму трёх элементов; средний элемент изначально нулевой.',
  'int solve(int a, int b) { auto buf = std::make_unique<int[]>(3); buf[0] = a; buf[2] = b; return buf[0] + buf[1] + buf[2]; }',
  'sum',
  'Хранит ли unique_ptr<T[]> длину массива?',
  'Нет: длину нужно вести отдельно',
  'Да: её возвращает size()',
  [
    'Объяснить, какое окно утечки закрывает make_unique по сравнению с парой new + владелец.',
    'Проследить на MemoryDiagram создание и очистку владеющего массива.',
    'Использовать make_unique<int[]> с инициализацией нулями и предсказать сумму элементов.',
  ],
  'Сравните две записи: new T(args) с последующим конструированием unique_ptr и make_unique<T>(args). В первой между шагами возможен бросающий код.',
);
add(
  'shared-ptr',
  'std::shared_ptr — совместное владение',
  'shared_ptr применяют, когда несколько независимых участников должны продлевать жизнь одного объекта и момент последнего использования заранее неизвестен. Копия указателя не копирует объект: участники разделяют владение через блок управления. Когда последний сильный владелец исчезает, управляемый объект уничтожается. Это дороже и сложнее исключительного владения — shared_ptr не является универсальным лекарством от непонятных сроков жизни.',
  'Новую долю владения получают только копированием существующего shared_ptr. Конструирование двух shared_ptr из одного сырого адреса создаёт независимые блоки управления: каждый удалит объект — double delete. shared_ptr(this) внутри метода — та же ошибка изнутри; для законной выдачи совладения существует enable_shared_from_this. make_shared совмещает выделение объекта и блока управления. const shared_ptr<T> запрещает менять указатель, но не объект; shared_ptr<const T> ограничивает изменение объекта. Атомарен счётчик, а не сам T: доступ к объекту из нескольких потоков требует отдельной синхронизации.',
  'first ──> блок управления: сильных 2 ──> объект A(4)\nsecond ──> тот же блок\nfirst.reset(): сильных 1; A жив\nsecond владеет A единолично; *second = 7\nsecond.reset(): сильных 0; A уничтожен',
  'Нельзя писать shared_ptr<T> second(first.get()) для получения совладельца — копируйте first. И не создавайте shared_ptr(this) для подключения к уже существующему владению.',
  'Скопируйте shared_ptr, измените int через второго владельца и прочитайте через первого: это намеренно общее состояние. Сравните с глубокой копией из предыдущих уроков, где значения независимы.',
  'int main() { auto first = std::make_shared<int>(4); auto second = first; *second += 3; first.reset(); std::cout << *second << " " << second.use_count() << "\\n"; }',
  '7 1\n',
  'В solve создайте first = make_shared<int>(a), скопируйте в second, измените объект через second прибавлением b, сбросьте first и верните *second. Не создавайте независимый блок управления из get().',
  'int solve(int a, int b) { auto first = std::make_shared<int>(a); auto second = first; *second += b; first.reset(); return *second; }',
  'sum',
  'Копирует ли копирование shared_ptr сам управляемый объект?',
  'Нет: копируется участие в общем владении',
  'Да: создаётся независимый объект T',
  [
    'Объяснить блок управления как источник совместного владения.',
    'Проследить на MemoryDiagram счётчик сильных владельцев через копии и reset.',
    'Разделить владение копированием и объяснить, почему конструирование из get() запрещено.',
  ],
  'Нарисуйте блок управления отдельно от объекта. Каждая копия shared_ptr добавляет сильного владельца; каждый reset или деструктор копии отнимает.',
);
add(
  'reference-counting',
  'Подсчёт ссылок — Reference counting',
  'Счётчик сильных владельцев меняется при копировании, разрушении, reset и присваивании shared_ptr. Ссылка shared_ptr<T>& нового владельца не создаёт и счётчик не увеличивает; перемещение передаёт существующую долю, оставляя источник пустым. use_count удобен для учебной трассировки в одном потоке, но не является протоколом блокировки: в многопоточной программе значение устаревает в момент возврата.',
  'Объект и блок управления живут по разным часам. При исчезновении последнего сильного владельца объект уничтожается; слабые наблюдатели могут удерживать блок управления, чтобы узнавать о смерти объекта. При make_shared объект и блок часто размещены в одном выделении, поэтому память возвращается аллокатору только после исчезновения слабых ссылок, хотя деструктор T уже выполнен. Проверка if (use_count() == 1) «можно менять безопасно» — ложное право: состояние может измениться между чтением и использованием.',
  'p = make_shared → сильных 1\nq = p           → сильных 2\nref = q по &    → сильных всё ещё 2\nr = move(q)     → сильных 2; q пуст\nвыход из блока  → сильных 1',
  'use_count() == 1 не даёт права менять объект без синхронизации в многопоточном коде. Счётчик — снимок прошлого, а не гарантия будущего.',
  'Добавьте функцию read(shared_ptr<int> p) и сравните счётчик внутри неё с read(const shared_ptr<int>& p). Если функция только читает int, рассмотрите ещё более простой const int&.',
  'int main() { auto p = std::make_shared<int>(1); { auto q = p; auto& ref = q; (void)ref; auto r = std::move(q); std::cout << p.use_count() << " "; } std::cout << p.use_count() << "\\n"; }',
  '2 1\n',
  'В solve создайте shared_ptr p(a). Во вложенном блоке сделайте q = p и r = move(q), сохраните p.use_count(). После блока верните 10 * сохранённый счётчик + текущий счётчик. Аргумент b не используется.',
  'int solve(int a, int b) { (void)b; auto p = std::make_shared<int>(a); int during; { auto q = p; auto r = std::move(q); during = static_cast<int>(p.use_count()); } return 10 * during + static_cast<int>(p.use_count()); }',
  '21',
  'Увеличивает ли перемещение shared_ptr число сильных владельцев?',
  'Нет: оно передаёт существующую долю владения',
  'Да: как любое присваивание',
  [
    'Перечислить операции, меняющие сильный счётчик, и операции, которые его не меняют.',
    'Проследить на MemoryDiagram счётчик через копию, ссылку, перемещение и выход из блока.',
    'Вычислить use_count в каждой точке трассировки и объяснить расхождение объекта и блока управления.',
  ],
  'Для каждой строки трассировки ответьте: появился ли новый владеющий shared_ptr? Ссылка и перемещение новых владельцев не создают.',
);
add(
  'weak-ptr',
  'std::weak_ptr — наблюдение без владения',
  'weak_ptr хранит возможность попытаться получить совместное владение, не продлевая жизнь объекта. Прямого доступа у него нет — operator* отсутствует намеренно. Единственный безопасный путь: lock() возвращает shared_ptr, который либо пуст (объект мёртв), либо удерживает живой объект на всё время своего существования. Сохраните результат в локальную переменную — так наблюдение превращается в ограниченный интервал владения.',
  'expired() сообщает, осталось ли сильное владение, но схема if (!weak.expired()) с последующим действием не закрепляет объект: между проверкой и доступом состояние может измениться даже в однопоточном коде с вложенными областями. lock объединяет проверку и получение владения атомарно относительно счётчика. Классические применения: обратное ребро child → parent, кеш с исчезающими объектами, подписки, где смерть получателя означает «пропустить уведомление». Заранее решите, что делать при отсутствии объекта: пропустить, вернуть fallback или сообщить об ошибке.',
  'owner → блок: сильных 1 → A(6)\nweak - - наблюдает -> блок; жизнь A не продлевает\nheld = weak.lock(): сильных 2\nowner.reset(): A жив благодаря held\nheld.reset(): A уничтожен; следующий lock пуст',
  'Не сохраняйте сырой адрес из временного weak.lock().get(): временный shared_ptr может быть последним владельцем и исчезнет в конце полного выражения.',
  'Удерживайте результат lock, сбросьте первоначального владельца и проверьте доступ через удержанный shared_ptr. Только после его reset наблюдатель становится expired.',
  'int main() { auto owner = std::make_shared<int>(6); std::weak_ptr<int> weak = owner; auto held = weak.lock(); owner.reset(); std::cout << *held << " "; held.reset(); std::cout << (weak.expired() ? 1 : 0) << "\\n"; }',
  '6 1\n',
  'В solve создайте owner(a) и weak-наблюдателя, получите held = weak.lock(), сбросьте owner, сохраните *held, затем сбросьте held. Верните сохранённое + b, только если последующий weak.lock() пуст; иначе -9999.',
  'int solve(int a, int b) { auto owner = std::make_shared<int>(a); std::weak_ptr<int> weak = owner; auto held = weak.lock(); owner.reset(); int saved = *held; held.reset(); return weak.lock() ? -9999 : saved + b; }',
  'sum',
  'Как безопасно получить объект через weak_ptr?',
  'Сохранить результат lock() и работать через него',
  'Проверить expired() и разыменовать weak_ptr',
  [
    'Объяснить, почему lock(), а не expired(), является безопасным способом доступа.',
    'Проследить на MemoryDiagram, как held продлевает жизнь объекта после reset владельца.',
    'Построить наблюдателя, который честно переживает смерть объекта и сообщает о ней.',
  ],
  'Проверьте паттерн на гонку: между expired() и действием объект может умереть. lock() возвращает владельца — с ним объект не умрёт, пока владелец жив.',
);
add(
  'cyclic-references',
  'Циклические ссылки — Cyclic references',
  'Подсчёт ссылок не является сборщиком мусора по достижимости: он удаляет объект при обнулении счётчика, а не при потере доступности из корней. Если A сильно владеет B, а B сильно владеет A, после исчезновения внешних владельцев оба счётчика остаются положительными. Объекты недостижимы для программы, но их деструкторы не запускаются. Разорвать цикл в деструкторе нельзя — до деструктора не доходит исполнение.',
  'Нарисуйте ориентированный граф владения отдельно от графа доступа. В дереве родитель владеет детьми через shared_ptr, а ребёнок наблюдает родителя через weak_ptr. Для общего графа выберите внешний реестр владельцев с невладеющими рёбрами или явный протокол teardown. Циклы прячутся и в замыканиях: объект хранит std::function, а лямбда захватила shared_ptr на этот же объект — граф владения объект → callback → объект. Не заменяйте все рёбра на weak без модели владения: узлы начнут исчезать слишком рано.',
  'Дефект: внешние p и q удалены\nA ──shared──> B и B ──shared──> A\nсильных у каждого: 1 → деструкторы не выполняются → утечка\nИсправление: A ──shared──> B; B - - weak - -> A\nВнешний владелец A исчезает → ~A → освобождение B → ~B',
  'Успешный stdout не доказывает отсутствие удержания: цикл проявляется только исчезновением деструкторов. Тест на утечку обязан завершить все внешние области владения, а наблюдатели в нём должны быть слабыми.',
  'В практике счётчик живых узлов должен вернуться к нулю после блока. Внешние weak-наблюдатели помогают проверить это, не удерживая узлы сами. Добавьте третий узел и определите, какие рёбра должны быть слабыми.',
  'struct Node { std::shared_ptr<Node> child; std::weak_ptr<Node> parent; };\nint main() { std::weak_ptr<Node> observer; { auto root = std::make_shared<Node>(); auto leaf = std::make_shared<Node>(); root->child = leaf; leaf->parent = root; observer = root; } std::cout << (observer.expired() ? 1 : 0) << "\\n"; }',
  '1\n',
  'Исправьте цикл: Node владеет child через shared_ptr, parent хранит weak_ptr. Счётчик live увеличивается конструктором и уменьшается деструктором. solve во вложенном блоке создаёт root и child, связывает их, сохраняет a + b и после блока возвращает сохранённое только при live == 0; иначе -9999.',
  'struct Node { int& live; std::shared_ptr<Node> child; std::weak_ptr<Node> parent; explicit Node(int& n): live(n) { ++live; } ~Node() { --live; } };\nint solve(int a, int b) { int live = 0, saved; { auto root = std::make_shared<Node>(live); auto child = std::make_shared<Node>(live); root->child = child; child->parent = root; saved = a + b; } return live == 0 ? saved : -9999; }',
  'sum',
  'Почему разрыв цикла в деструкторе не решает проблему удержания?',
  'До деструктора не доходит исполнение: сильные счётчики не равны нулю',
  'Потому что shared_ptr всегда удаляет объект слишком рано',
  [
    'Отличать сборку по достижимости от подсчёта ссылок на примере цикла.',
    'Проследить на MemoryDiagram, почему счётчики цикла никогда не обнуляются.',
    'Диагностировать цикл сильного владения и разорвать его слабым обратным ребром.',
  ],
  'Нарисуйте граф владения и найдите достижимость из корней программы. Узлы, которых нет в графе достижимости, но чьи счётчики положительны, — цикл.',
);
add(
  'custom-deleters',
  'Пользовательские функции освобождения — Custom deleters',
  'Ресурс должен освобождаться парной операцией своего API: new/delete, new[]/delete[], malloc/free, fopen/fclose, библиотечные create/destroy. Пользовательский deleter сохраняет RAII для ресурса, который не удаляется обычным delete. В unique_ptr<T, D> тип deleter входит в тип владельца — способ освобождения не может потеряться при передаче. Deleter может хранить состояние: счётчик закрытий, контекст библиотеки, аллокатор; это влияет на размер и перемещение владельца.',
  'Для FILE определите Fclose с void operator()(FILE*) const noexcept, вызывающим fclose, и храните unique_ptr<FILE, Fclose>; результат fopen проверяйте через bool владельца — deleter не вызывается для null. shared_ptr принимает deleter при создании, но хранит его в блоке управления: тип не входит в shared_ptr<T>; make_shared пользовательский deleter не принимает. Ошибку fflush/fclose, важную приложению, обрабатывайте явной close-операцией до деструктора: бросать из деструктора нельзя. Заимствованный контекст внутри deleter обязан пережить все пути освобождения: reset, присваивание, разрушение перемещённого владельца.',
  'owner: указатель на ресурс + deleter с контекстом\nreset или разрушение owner\n→ вызов deleter(resource)\n→ парная операция освобождения ровно один раз\nДля null deleter не вызывается; контекст жив до завершения вызова',
  'Нельзя закрывать FILE через delete или освобождать память из new через free — несовместимые пары. Пустой deleter, который ничего не освобождает, маскирует утечку вместо владения.',
  'В практике deleter хранит указатель на счётчик. Переместите owner и убедитесь, что закрытие учитывается ровно один раз. Затем переставьте объявления счётчика и владельца на бумаге и объясните зависимость времени жизни.',
  'struct CountingDelete { int* count; void operator()(int* p) const noexcept { ++*count; delete p; } };\nint main() { int count = 0; { std::unique_ptr<int, CountingDelete> p(new int(3), CountingDelete{&count}); auto q = std::move(p); std::cout << *q << " "; } std::cout << count << "\\n"; }',
  '3 1\n',
  'Создайте CountingDelete, увеличивающий внешний счётчик и удаляющий int. solve создаёт unique_ptr<int, CountingDelete> со значением a, перемещает его во второго владельца, сохраняет значение + b, вызывает reset дважды и возвращает сохранённое при count == 1; иначе -9999. Счётчик объявите раньше владельцев.',
  'struct CountingDelete { int* count; void operator()(int* p) const noexcept { ++*count; delete p; } };\nint solve(int a, int b) { int count = 0; std::unique_ptr<int, CountingDelete> p(new int(a), CountingDelete{&count}); auto q = std::move(p); int saved = *q + b; q.reset(); q.reset(); return count == 1 ? saved : -9999; }',
  'sum',
  'До какого момента обязан существовать контекст, заимствованный deleter?',
  'До завершения освобождения ресурса на любом пути: reset, присваивание, деструктор',
  'Только во время создания владельца',
  [
    'Объяснить, почему ресурс освобождается парной операцией своего API.',
    'Проследить на MemoryDiagram вызов deleter ровно один раз при перемещении и reset.',
    'Реализовать deleter с заимствованным счётчиком и проверить порядок объявления жизней.',
  ],
  'Проверьте deleter на трёх путях освобождения: reset, присваивание нового адреса, разрушение владельца. На каждом парная операция должна выполниться ровно один раз.',
);
